WITH source AS (SELECT mktcode,tgtcode,bizdate,volume,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate DESC) AS seq FROM `newzl`.`hsj_stock_hq_basic`), metrics AS (SELECT mktcode,tgtcode,SUM(CASE WHEN volume>0 THEN 1 ELSE 0 END) AS hits,COUNT(*) AS total FROM source WHERE seq<=5 GROUP BY mktcode,tgtcode), qualified AS (SELECT mktcode,tgtcode FROM metrics WHERE total>0 AND hits<>total) SELECT a.mktcode,a.tgtcode,a.bizdate FROM (SELECT mktcode,tgtcode,bizdate FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14') a JOIN qualified q ON q.mktcode=a.mktcode AND q.tgtcode=a.tgtcode;
